#include "field_mod.hpp"
#include <flint/nmod_poly.h>
#include <flint/nmod_poly_mat.h>
#include <flint/nmod_poly_factor.h>
void eval(nmod_poly_t out,const nmod_mpoly_t in){Rat temp;nmod_mpoly_evaluate_one_ui(temp.n,in,0,2,ctx);assert(nmod_mpoly_get_nmod_poly(out,temp.n,1,ctx));}
int main(int argc,char**argv){nmod_mpoly_ctx_init(ctx,2,ORD_LEX,prime);{ifstream in(argv[1]);int nr,nc;in>>nr>>nc;vector<int>pivs;vector<Row>A(nr);for(auto&row:A){int piv,n;in>>piv>>n;pivs.push_back(piv);for(int k=0;k<n;k++){int j;in>>j;Rat x;readpoly(in,x.n);readpoly(in,x.d);row.emplace(j,std::move(x));}}nmod_poly_mat_t B;nmod_poly_mat_init(B,nr,nr,prime);nmod_poly_t a,b,g,q,r,det;nmod_poly_init(a,prime);nmod_poly_init(b,prime);nmod_poly_init(g,prime);nmod_poly_init(q,prime);nmod_poly_init(r,prime);nmod_poly_init(det,prime);for(int i=0;i<nr;i++)for(int j=0;j<nr;j++){auto it=A[i].find(pivs[j]);if(it==A[i].end())continue;eval(a,it->second.n);eval(b,it->second.d);assert(nmod_poly_degree(b)==0);nmod_poly_scalar_mul_nmod(nmod_poly_mat_entry(B,i,j),a,n_invmod(nmod_poly_get_coeff_ui(b,0),prime));}nmod_poly_mat_det_interpolate(det,B);cerr<<"DET "<<nmod_poly_degree(det)<<'\n';ifstream fs(argv[2]);int n;fs>>n;for(int k=0;k<n;k++){Rat f;readpoly(fs,f.n);eval(a,f.n);int removed=0;while(true){nmod_poly_gcd(g,det,a);int d=nmod_poly_degree(g);if(d<=0)break;nmod_poly_divrem(q,r,det,g);assert(nmod_poly_is_zero(r));nmod_poly_swap(q,det);removed+=d;}cerr<<"FACTOR "<<k<<" removed "<<removed<<'\n';}cerr<<"REMAIN "<<nmod_poly_degree(det)<<'\n';ofstream out(argv[3]);out<<nmod_poly_degree(det)<<'\n';for(int j=0;j<=nmod_poly_degree(det);j++)out<<nmod_poly_get_coeff_ui(det,j)<<' ';out<<'\n';nmod_poly_factor_t fac;nmod_poly_factor_init(fac);nmod_poly_factor(fac,det);for(int j=0;j<fac->num;j++){cerr<<"irreducible "<<nmod_poly_degree(fac->p+j)<<" exponent "<<fac->exp[j]<<'\n';}nmod_poly_factor_clear(fac);for(auto v:{a,b,g,q,r,det})nmod_poly_clear(v);nmod_poly_mat_clear(B);}nmod_mpoly_ctx_clear(ctx);flint_cleanup();}
